package org.apache.commons.math.analysis;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MaxIterationsExceededException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for BrentSolver#solve(double, double)
 */
public class BrentSolver_solve_TriageGen1Test {

    /**
     * Test case for a standard successful root finding scenario.
     * This covers the 'else' branch where signs are different.
     */
    @Test
    public void testSolve_Success() throws MaxIterationsExceededException, FunctionEvaluationException {
        // f(x) = x^2 - 2, root at sqrt(2) approx 1.41421356
        UnivariateRealFunction f = x -> x * x - 2.0;
        BrentSolver solver = new BrentSolver(f);

        double min = 0.0;
        double max = 2.0;
        double result = solver.solve(min, max);

        Assert.assertEquals(Math.sqrt(2.0), result, 1e-10);
    }

    /**
     * Test case where the function values at endpoints have the same sign.
     * This covers the 'if (sign >= 0)' branch and the IllegalArgumentException.
     */
    @Test(expected = IllegalArgumentException.class)
    public void testSolve_SameSign_ThrowsException() throws MaxIterationsExceededException, FunctionEvaluationException {
        // f(x) = x^2 + 1, no real roots, always positive
        UnivariateRealFunction f = x -> x * x + 1.0;
        BrentSolver solver = new BrentSolver(f);

        double min = -1.0;
        double max = 1.0;
        // Should throw IllegalArgumentException because yMin * yMax > 0
        solver.solve(min, max);
    }

    /**
     * Test case where one of the endpoints is exactly zero.
     * This covers the edge case where sign might be 0.
     */
    @Test(expected = IllegalArgumentException.class)
    public void testSolve_ZeroAtEndpoint_ThrowsException() throws MaxIterationsExceededException, FunctionEvaluationException {
        // f(x) = x, at min=0, f(0)=0. sign = 0 * 1 = 0.
        // The code logic 'if (sign >= 0)' will catch this and throw IllegalArgumentException
        UnivariateRealFunction f = x -> x;
        BrentSolver solver = new BrentSolver(f);

        double min = 0.0;
        double max = 1.0;
        solver.solve(min, max);
    }

    /**
     * Test case to trigger FunctionEvaluationException.
     * This ensures the exception propagates correctly.
     */
    @Test(expected = FunctionEvaluationException.class)
    public void testSolve_FunctionEvaluationException() throws MaxIterationsExceededException, FunctionEvaluationException {
        UnivariateRealFunction f = x -> {
            throw new FunctionEvaluationException(new RuntimeException("Eval error"));
        };
        BrentSolver solver = new BrentSolver(f);

        solver.solve(-1.0, 1.0);
    }

    /**
     * Test case to trigger MaxIterationsExceededException.
     * We use a function that converges extremely slowly or is designed to fail.
     */
    @Test(expected = MaxIterationsExceededException.class)
    public void testSolve_MaxIterationsExceeded() throws MaxIterationsExceededException, FunctionEvaluationException {
        // A function that is difficult to converge for Brent's method
        // Or we can simulate it by providing a function that returns values 
        // that make the interval shrink extremely slowly.
        // For unit testing purposes, we assume the underlying solver logic 
        // can be forced into this state.

        // Using a very high precision requirement or a pathological function:
        UnivariateRealFunction f = x -> Math.sin(1.0 / x); 
        // Note: BrentSolver might handle this differently, but for coverage:
        BrentSolver solver = new BrentSolver(f);

        // This is a heuristic to try and trigger the exception if the interval is problematic
        solver.solve(0.000000001, 1.0);
    }
}
